which node && node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
console.log(db.prepare('SELECT name FROM sqlite_master WHERE type=\"table\"').all());
" 2>/dev/null || echo "no better-sqlite3"

node -e "
const Database = require('/tmp/node_modules/better-sqlite3');
const db = new Database('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table' ORDER BY name\").all();
console.log('Tables:', tables.map(t=>t.name));
const settings = db.prepare('SELECT * FROM ts_device_settings').all();
console.log('Device settings:', JSON.stringify(settings, null, 2));
"
